# aplicar-v64-suporte-com-solicitacoes-e-hero-admin.ps1
# Ajusta duas coisas:
# 1. Centraliza solicitacoes de virar ADMIN dentro da tela /admin/support.
# 2. Padroniza o retangulo/hero do comeco das telas admin.
#
# Rotas finais:
# - /admin/support -> central de suporte
# - /admin/support?tab=admin-requests -> solicitacoes de criador
# - /admin/support/admin-requests -> redireciona para /admin/support?tab=admin-requests

$ErrorActionPreference = "Stop"

$Root = Get-Location
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Write-TextBase64File($RelativePath, $Base64Content) {
  $Target = Join-Path $Root $RelativePath
  $TargetDir = Split-Path $Target -Parent

  if (-not (Test-Path $TargetDir)) {
    New-Item -ItemType Directory -Path $TargetDir -Force | Out-Null
  }

  if (Test-Path $Target) {
    $Backup = "$Target.bak-v64-$Stamp"
    Copy-Item $Target $Backup -Force
    Write-Host "Backup criado: $Backup" -ForegroundColor DarkGray
  }

  $Content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Base64Content))
  Set-Content -Path $Target -Value $Content -Encoding UTF8
  Write-Host "Atualizado: $RelativePath" -ForegroundColor Green
}

function Patch-HeaderLinks() {
  $HeaderPath = Join-Path $Root "apps\web\src\components\customer\CustomerHeader.tsx"

  if (-not (Test-Path $HeaderPath)) {
    Write-Host "Aviso: CustomerHeader.tsx nao encontrado para ajustar link do suporte." -ForegroundColor Yellow
    return
  }

  $Content = Get-Content $HeaderPath -Raw
  $Original = $Content

  $Content = $Content.Replace('/admin/support/admin-requests', '/admin/support?tab=admin-requests')
  $Content = $Content.Replace('Atendimentos", href: "/admin/support?tab=admin-requests"', 'Atendimentos", href: "/admin/support"')

  if ($Content -ne $Original) {
    $Backup = "$HeaderPath.bak-v64-$Stamp"
    Copy-Item $HeaderPath $Backup -Force
    Set-Content -Path $HeaderPath -Value $Content -Encoding UTF8
    Write-Host "Header atualizado: solicitacoes agora ficam dentro de /admin/support" -ForegroundColor Green
  } else {
    Write-Host "Header sem alteracoes." -ForegroundColor Yellow
  }
}

function Patch-AdminHeroStyles() {
  $PatchScriptPath = Join-Path $Root ".tmp-v64-padronizar-hero-admin.js"

  $NodeScript = @'
const fs = require('fs');
const path = require('path');

const root = process.cwd();
const adminDir = path.join(root, 'apps', 'web', 'src', 'app', 'admin');
const extensions = new Set(['.tsx', '.ts']);

const standard = 'rounded-[28px] bg-gradient-to-r from-orange-500 via-orange-700 to-[#19002f] p-8 text-white shadow-sm';

function walk(dir) {
  if (!fs.existsSync(dir)) return [];

  const entries = fs.readdirSync(dir, { withFileTypes: true });
  const files = [];

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      files.push(...walk(fullPath));
    } else if (extensions.has(path.extname(entry.name))) {
      files.push(fullPath);
    }
  }

  return files;
}

function backup(file) {
  fs.copyFileSync(file, `${file}.bak-v64-${Date.now()}`);
}

let patched = 0;

for (const file of walk(adminDir)) {
  let content = fs.readFileSync(file, 'utf8');
  const original = content;

  content = content.replaceAll(
    'rounded-[28px] bg-gradient-to-r from-orange-500 to-[#19002f] p-8 text-white',
    standard,
  );

  content = content.replaceAll(
    'rounded-[28px] bg-gradient-to-r from-orange-500 via-orange-700 to-[#19002f] p-8 text-white',
    standard,
  );

  content = content.replaceAll(
    'rounded-[28px] bg-gradient-to-r from-[#19002f] to-orange-500 p-8 text-white',
    standard,
  );

  content = content.replaceAll(
    'rounded-[28px] bg-gradient-to-r from-[#19002f] via-neutral-950 to-orange-500 p-8 text-white',
    standard,
  );

  content = content.replaceAll(
    'rounded-[28px] bg-gradient-to-r from-[#19002f] via-[#0b1020] to-[#0b3b5a] p-8 text-white',
    standard,
  );

  content = content.replaceAll(
    'rounded-[28px] bg-gradient-to-r from-[#19002f] via-[#0b1020] to-[#0b3b5a] p-8 text-white shadow-sm',
    standard,
  );

  content = content.replaceAll(
    'rounded-[28px] bg-gradient-to-r from-orange-500 via-orange-700 to-[#19002f] p-8 text-white shadow-sm shadow-sm',
    standard,
  );

  if (content !== original) {
    backup(file);
    fs.writeFileSync(file, content, 'utf8');
    patched += 1;
    console.log(`Hero padronizado: ${path.relative(root, file)}`);
  }
}

console.log(`Arquivos admin com hero padronizado: ${patched}`);
'@

  Set-Content -Path $PatchScriptPath -Value $NodeScript -Encoding UTF8

  Write-Host "Padronizando retangulos/heros das telas admin..." -ForegroundColor Cyan
  node $PatchScriptPath

  if ($LASTEXITCODE -ne 0) {
    throw "Falha ao padronizar heros admin."
  }
}

Write-Host "Aplicando v64 - suporte com solicitacoes + hero admin padrao..." -ForegroundColor Cyan

